  const summary = summarize(transactions, range);
  const [py, pm] = month.split('-').map(Number);
  const prevMonth = pm === 1
    ? String(py - 1).padStart(4, '0') + '-12'
    : String(py).padStart(4, '0') + '-' + String(pm - 1).padStart(2, '0');
  const prev = summarize(transactions, { from: prevMonth + '-01', to: prevMonth + '-31' });

  reportBody.innerHTML = '';
  const categories = [...Object.keys(summary.byCategory)];
  for (const cat of Object.keys(prev.byCategory)) {
    if (!categories.includes(cat)) categories.push(cat);
  }
  for (const cat of categories) {
    const cur = Math.round((summary.byCategory[cat] || 0) * 100);
    const old = Math.round((prev.byCategory[cat] || 0) * 100);
    const diff = cur - old;
    const tr = document.createElement('tr');

    const tdCat = document.createElement('td');
    tdCat.textContent = cat;

    const tdTotal = document.createElement('td');
    tdTotal.textContent = (cur / 100).toFixed(2);

